import os
from typing import List, Dict, Any
from azure.ai.documentintelligence import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential


def validate_structured_document(
    document_path: str, 
    required_fields: List[str], 
    min_confidence: float = 0.85
) -> Dict[str, Any]:
    """
    Extracts structured fields from a document using Azure AI Document Intelligence
    and validates the presence of required fields and their confidence scores.
    """
    endpoint = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise EnvironmentError(
            "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY must be set."
        )

    client = DocumentAnalysisClient(
        endpoint=endpoint, 
        credential=AzureKeyCredential(key)
    )

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document("prebuilt-document", document=f)
        result = poller.result()

    extracted = {}
    for doc in result.documents:
        for field_name, field_info in doc.fields.items():
            extracted[field_name] = {
                "value": field_info.content,
                "confidence": field_info.confidence
            }

    validation_report = {
        "valid": True,
        "missing_fields": [],
        "low_confidence_fields": []
    }

    for field in required_fields:
        if field not in extracted:
            validation_report["valid"] = False
            validation_report["missing_fields"].append(field)
        else:
            conf = extracted[field]["confidence"]
            if conf is not None and conf < min_confidence:
                validation_report["valid"] = False
                validation_report["low_confidence_fields"].append({
                    "field": field,
                    "confidence": conf
                })

    return validation_report
